INSERT INTO wiki_chunks (id,page_path,ordinal,heading_path,text,token_count,source_refs_json,content_sha) SELECT json_extract(value,'$[0]'),json_extract(value,'$[1]'),json_extract(value,'$[2]'),json_extract(value,'$[3]'),json_extract(value,'$[4]'),json_extract(value,'$[5]'),json_extract(value,'$[6]'),json_extract(value,'$[7]') FROM json_each('[["chunk_59cb4b3b29a1b8fe073d68ba","wiki/sources/ril-438-inb-2026-data.md",131,"Seite 80","Â§Â§ 33, 34\n\nÂ§ 33\n\nVorspann\n\nZahl der Trieb- (1) Ein Zug darf zwei Triebfahrzeuge an der Spitze fÃ¼hren. Der\n\nfahrzeuge EBL kann Abweichungen zulassen. Elektrische Lokomotiven sollen dabei vor Diesel- oder Dampflokomotiven, Diesellokomotiven\n\nvor Dampflokomotiven fahren.\n\nAufgabe des (2) Der FÃ¼hrer des vorderen Triebfahrzeugs trÃ¤gt in erster Linie\n\nersten Triebfahr- die Verantwortung fÃ¼r das Geben der Signale und die Beobachtung\n\nzeugfÃ¼hrers der Strecke und ihrer Signale.\n\nAufgaben des (3) Der FÃ¼hrer des zweiten Triebfahrzeugs hat auf die Signale\n\nTriebfahrzeug- und Mitteilungen des FÃ¼hrers des vorderen Triebfahrzeugs zu achfÃ¼hrers des ten und den Zug zu beobachten. Zur Beobachtung der Strecke\n\nzweiten Trieb- und ihrer Signale ist er ebenfalls verpflichtet.\n\nfahrzeugs\n\nUnterwegs (4) Ist unterwegs zu rangieren, so ist das vordere Triebfahrzeug\n\nrangieren in der Regel abzuhÃ¤ngen. Es ist immer abzuhÃ¤ngen, wenn Wagen\n\nabgestoÃŸen werden sollen.\n\nMehrfach- (5) Die Bestimmungen (2) bis (4) gelten nicht fÃ¼r Triebfahrzeuge, die\n\ntraktion gemeinsam von einem FÃ¼hrerstand aus gesteuert werden.\n\nÂ§ 34\n\nGeschobene ZÃ¼ge\n\nBegriff (1) Geschobene ZÃ¼ge sind ZÃ¼ge, deren Triebfahrzeuge nicht an\n\nder Spitze laufen und die nicht von der Spitze aus gesteuert werden. HilfszÃ¼ge mit SchneerÃ¤umern auf eigenen RÃ¤dern und Schneeschleudern gelten betrieblich nicht als geschobene ZÃ¼ge.\n\nZulÃ¤ssigkeit (2) Es dÃ¼rfen geschoben werden:\n\na) A rbeitszÃ¼ge, dienstliche SonderzÃ¼ge,\n\nb) ZÃ¼ge nach und von Anschlussstellen,\n\nc) Z Ã¼ge bei besonderen Ã¶rtlichen VerhÃ¤ltnissen mit Genehmigung des EBL,\n\nd) Z Ã¼ge in StÃ¶rungsfÃ¤llen.\n\nKuppeln (3) Schiebende Triebfahrzeuge mÃ¼ssen mit dem Zug gekuppelt sein.\n\nâ€“ 60 â€“",241,"{\"canonical_url\":\"https://www.dbinfrago.com/resource/blob/13174622/b60c3e17d5793a2e92c45c5499bc5362/Ril-438-INB-2026-data.pdf\",\"normalized_sha256\":\"896af7cb568779272b6567f3e92facbd6eb0db60f9e6d474fac6b4b555777da5\",\"page\":80,\"source_id\":\"src_756ac05064c14207f798\",\"source_sha256\":\"f01276e5713c693152de0735b74de84079760d1b3cbcf4727396e73538ad50e0\",\"source_version_id\":\"sv_4f517b21bbdd70a0c6fcfe5c\"}","a63e59c4fb03338cb709ea5d3db7c9c22c8b4d92f0164058d07b8ae00367bdd0"],["chunk_ad00cd0c1c1486039e790dd5","wiki/sources/ril-438-inb-2026-data.md",132,"Seite 81","Â§Â§ 34, 35\n\n(4) Das vorderste Fahrzeug ist mit einem Betriebsbediensteten Besetzung des\n\nzu be setzen, der eine Signalpfeife â€“ auf Strecken mit nichttechnisch vordersten\n\ngesicherten BahnÃ¼bergÃ¤ngen auch ein Signalhorn â€“ und bei Dunkel- Fahrzeuges\n\nheit eine weiÃŸleuchtende Handlampe mitfÃ¼hrt. Er beobachtet die\n\nStrecke und gibt erforderlichenfalls AuftrÃ¤ge und Haltsignale an\n\nden TriebfahrzeugfÃ¼hrer. An den Signalen BÃ¼ 4, Pf 2 und BÃ¼ 5 und\n\nauÃŸerdem mehrmals vor dem Befahren des BahnÃ¼bergangs hat\n\ner mit dem Signalhorn zu blasen. Der TriebfahrzeugfÃ¼hrer muss die\n\nSignale dieses Bediensteten aufnehmen kÃ¶nnen.\n\nÂ§ 35\n\nNachgeschobene ZÃ¼ge\n\n(1) Nachgeschobene ZÃ¼ge sind ZÃ¼ge, deren Triebfahrzeuge an der Begriff\n\nSpitze laufen oder die von der Spitze aus gesteuert werden und die\n\nein weiteres Triebfahrzeug nachschiebt, das nicht von der Spitze aus\n\ngesteuert wird.\n\nAls nachschiebende Triebfahrzeuge gelten auch Triebwagen mit Nachschiebennormalen Zug- und StoÃŸeinrichtungen, die zum Nachschieben ver- des Triebfahzeug\n\nwendet werden.\n\n(2) ZÃ¼ge dÃ¼rfen nachgeschoben werden ZulÃ¤ssigkeit\n\na) bei der Abfahrt,\n\nb) a uf Steigungsstrecken einschlieÃŸlich dazwischenliegender\n\nwaagerechter und im GefÃ¤lle liegender Strecken,\n\nc) im Notfall Ã¼berall.\n\nAuf welchen Strecken regelmÃ¤ÃŸig nachgeschoben werden darf, bestimmt der EBL.\n\nBei regelmÃ¤ÃŸigem Nachschieben wird vom EBL, sonst mit schriftlichem Befehl vorgeschrieben, bis zu welchem Bahnhof das nachschiebende Triebfahrzeug mitfÃ¤hrt oder von welchem Punkt der\n\nfreien Strecke es zurÃ¼ckfÃ¤hrt.\n\n(3) Nachschiebende Triebfahrzeuge sind mit dem Zug zu kuppeln, Kuppeln\n\nwenn sie auf einer im GefÃ¤lle liegenden Strecke mitfahren.",227,"{\"canonical_url\":\"https://www.dbinfrago.com/resource/blob/13174622/b60c3e17d5793a2e92c45c5499bc5362/Ril-438-INB-2026-data.pdf\",\"normalized_sha256\":\"896af7cb568779272b6567f3e92facbd6eb0db60f9e6d474fac6b4b555777da5\",\"page\":81,\"source_id\":\"src_756ac05064c14207f798\",\"source_sha256\":\"f01276e5713c693152de0735b74de84079760d1b3cbcf4727396e73538ad50e0\",\"source_version_id\":\"sv_4f517b21bbdd70a0c6fcfe5c\"}","32f720cdde059395f2a065ced1c12decbd60084587bb342364674358bbbf38fe"],["chunk_d8508f5e5b67c30c8934ace8","wiki/sources/ril-438-inb-2026-data.md",133,"Seite 81","(4) Es darf hÃ¶chstens mit zwei Triebfahrzeugen nachgeschoben wer- Anzahl der nachden, die stets miteinander zu kuppeln sind. schiebenden\n\nTriebfahrzeuge\n\n(5) ZÃ¼ge mit Wagen, die nur durch die Ladung oder zusÃ¤tzlich durch Wagen durch\n\nSteifkupplung verbunden sind, dÃ¼rfen nicht nachgeschoben werden. Ladung oder\n\nSteifkupplung\n\nverbunden\n\nâ€“ 61 â€“",48,"{\"canonical_url\":\"https://www.dbinfrago.com/resource/blob/13174622/b60c3e17d5793a2e92c45c5499bc5362/Ril-438-INB-2026-data.pdf\",\"normalized_sha256\":\"896af7cb568779272b6567f3e92facbd6eb0db60f9e6d474fac6b4b555777da5\",\"page\":81,\"source_id\":\"src_756ac05064c14207f798\",\"source_sha256\":\"f01276e5713c693152de0735b74de84079760d1b3cbcf4727396e73538ad50e0\",\"source_version_id\":\"sv_4f517b21bbdd70a0c6fcfe5c\"}","aefe78cfc30fe174bffc07df54696c981107187b97a120971df5e49cb79e5604"],["chunk_301a92841a3bef76679bc1f6","wiki/sources/ril-438-inb-2026-data.md",134,"Seite 82","Â§Â§ 35, 36\n\nMitnahme (6) Zwischen dem Schlusswagen des Zuges und dem nachschievon Wagen benden Triebfahrzeug dÃ¼rfen beim Nachschieben im Bahnhof bis\n\nzu zwei mit dem nachschiebenden Triebfahrzeug gekuppelte Wagen\n\nlaufen.\n\nEinem mit dem Zug gekuppelten nachschiebenden Triebfahrzeug\n\ndÃ¼rfen Wagen angehÃ¤ngt werden. Der letzte Wagen muss eine wirkende Bremse haben.\n\nAnsetzen des (7) Das nachschiebende Triebfahrzeug hat sich vor der Abfahrt\n\nnachschieben- an den Zug zu setzen. Dann gibt ihr FÃ¼hrer zum Zeichen, dass er\n\nden Trieb- zum Schieben bereit ist, das Achtungssignal. Auf den Abfahrauffahrzeugs, trag gibt der FÃ¼hrer des vordersten Triebfahrzeugs gleichfalls das\n\nAbfahrt Achtungssignal, das der FÃ¼hrer des nachschiebenden Triebfahrzeugs beantwortet, wenn er zu schieben beginnt. Der EBL kann eine\n\nandere VerstÃ¤ndigung zulassen.\n\nBremsen (8) Der FÃ¼hrer des vordersten Triebfahrzeugs hat das Achtungssignal zu geben, bevor er die durchgehende Bremse in TÃ¤tigkeit setzt.\n\nBeendigung des (9) Wenn der FÃ¼hrer des nachschiebenden Triebfahrzeugs das\n\nNachschiebens Nachschieben auf der Strecke beendet, gibt er das Achtungssignal.\n\nDer EBL kann eine andere Art der VerstÃ¤ndigung zulassen.\n\nTrennung vom (10) Ein nachschiebendes Triebfahrzeug, das sich ohne Absicht vom\n\nZug Zug getrennt hat, darf sich erst wieder ansetzen, wenn der Zug zum\n\nStehen gekommen ist.\n\nÂ§ 36\n\nFahrten mit Nebenfahrzeugen\n\nFÃ¼hren von (1) Nebenfahrzeuge mÃ¼ssen von einem zur FÃ¼hrung berechtig-\n\nNebenfahr- â€¢ ten, streckenkundigen TriebfahrzeugfÃ¼hrer gefahren bzw. begleitet\n\nzeugen werden. Er ist fÃ¼r die Sicherheit der Fahrt und das Anbringen der\n\nSignale verantwortlich und hat ein Signalhorn, eine Signalfahne,\n\ndie erforderlichen SchlÃ¼ssel und bei Dunkelheit oder unsichtigem",244,"{\"canonical_url\":\"https://www.dbinfrago.com/resource/blob/13174622/