INSERT INTO wiki_chunks (id,page_path,ordinal,heading_path,text,token_count,source_refs_json,content_sha) SELECT json_extract(value,'$[0]'),json_extract(value,'$[1]'),json_extract(value,'$[2]'),json_extract(value,'$[3]'),json_extract(value,'$[4]'),json_extract(value,'$[5]'),json_extract(value,'$[6]'),json_extract(value,'$[7]') FROM json_each('[["chunk_3b285f9fc55f9f5197c650e4","wiki/sources/ril-438-inb-2026-data.md",191,"Seite 117","Â§ 62\n\nÂ§ 62\n\nRangierfahrten im gesperrten Bahnhofsgleis\n\nund im Baugleis\n\n(1) Bei Rangierfahrten im gesperrten Bahnhofsgleis und im Baugleis\n\ngelten die in der betrieblichen Anweisung (sofern aufgestellt) getroffenen Regelungen und zusÃ¤tzlich zu den Bestimmungen des Abschnittes IV Rangierdienst:\n\na) Der TriebfahrzugfÃ¼hrer ist Ã¼ber die Lage der Arbeitsstelle zu\n\nunterrichten.\n\nb) Alle Fahrzeuge sind an die durchgehende Bremse anzuschlieÃŸen.\n\nc) Die Rangierfahrt muss von der Spitze aus gesteuert sein oder\n\ndie Spitze der Rangierfahrt muss mit einem Rangierbegleiter besetzt sein. Auf das Besetzen des Fahrzeugs an der\n\nSpitze darf verzichtet werden, wenn\n\nâ€“ nur ein Fahrzeug geschoben wird und\n\nâ€“ der TriebfahrzeugfÃ¼hrer den Fahrweg beobachten kann und\n\nâ€“ eine Person unmittelbar vor Ingangsetzen der Fahrt das\n\nFrei sein des Fahrwegs von BeschÃ¤ftigten direkt vor dem\n\nersten Fahrzeug feststellt.\n\nd) Wenn sich der TriebfahrzeugfÃ¼hrer an der Spitze der Rangierfahrt, aber nicht im FÃ¼hrerraum befindet, muss er mit\n\neinem Signalhorn ausgerÃ¼stet sein. Wenn ein Rangierbegleiter die Spitze der Rangierfahrt besetzt, muss dieser in\n\nFunkkontakt mit dem TriebfahrzeugfÃ¼hrer stehen, einen Luftbremskopf verwenden und mit einem Signalhorn ausgerÃ¼stet sein.\n\ne) Die Rangiergeschwindigkeit betrÃ¤gt hÃ¶chstens 20 km/h.\n\nf) Der Mitarbeiter an der Spitze der Rangierfahrt muss Personen\n\nan und im Gleis mit Signal Zp 1 warnen.\n\ng) Die Rangierfahrt muss vor im Gleis befindlichen Personen anhalten, wenn diese das Gleis nicht verlassen.\n\n(2) Die MaÃŸnahmen nach a) und b) sowie die Verwendung des Luftbremskopfes kÃ¶nnen entfallen, wenn sich keine BeschÃ¤ftigten im\n\nGleis befinden oder die BeschÃ¤ftigten dem\n\nFahrdienstleiter | Zugleiter\n\nbzw. WeichenwÃ¤rter die RÃ¤umung des Gleises bestÃ¤tigt haben.\n\nâ€“ 93 â€“",256,"{\"canonical_url\":\"https://www.dbinfrago.com/resource/blob/13174622/b60c3e17d5793a2e92c45c5499bc5362/Ril-438-INB-2026-data.pdf\",\"normalized_sha256\":\"896af7cb568779272b6567f3e92facbd6eb0db60f9e6d474fac6b4b555777da5\",\"page\":117,\"source_id\":\"src_756ac05064c14207f798\",\"source_sha256\":\"f01276e5713c693152de0735b74de84079760d1b3cbcf4727396e73538ad50e0\",\"source_version_id\":\"sv_4f517b21bbdd70a0c6fcfe5c\"}","b48a82e0f366838583f85786499f9a9bca0d077e3de8f4911a614761ad1abf69"],["chunk_b48364d6326dffc79b99f612","wiki/sources/ril-438-inb-2026-data.md",192,"Seite 118","Anlage 1\n\nzu Â§ 1 (4)\n\nBesondere Bestimmungen fÃ¼r den Betrieb\n\nauf elektrifizierter Infrastruktur\n\nDie nachfolgenden Bestimmungen gelten grundsÃ¤tzlich fÃ¼r jede Infrastruktur mit elektrischer Fahrleitung, unabhÃ¤ngig von der Traktionsart der eingesetzten Fahrzeuge. Sie gelten auch fÃ¼r abgestellte Fahrzeuge und bei ruhendem Fahrbetrieb.\n\nDer EBL prÃ¼ft, ob und ggf. welche zusÃ¤tzliche Bestimmungen zu erlassen sind. Dabei\n\nmuss er insbesondere die Art der Fahrleitung(en) (Oberleitung/Stromschiene), die Fahrleitungsspannung(en) und bei Oberleitungen die FahrdrahthÃ¶hen berÃ¼cksichtigen.\n\nI. G efÃ¤hrdungen aus dem elektrischen Bahnbetrieb\n\nâ€¢\n\n(1) Beim Betrieb auf elektrifizierter Infrastruktur ist wegen der vom elektrischen Strom\n\nausgehenden GefÃ¤hrdung, erhÃ¶hte Vorsicht geboten. Die Mitarbeiter im Eisenbahnbe-\n\nâ€¢ trieb, die auf elektrifizierter Infrastruktur eingesetzt werden, mÃ¼ssen Ã¼ber die GefÃ¤hrdun-\n\nâ€¢ gen aus dem elektrischen Bahnbetrieb und die mÃ¶glichen Gefahren bei unsachgemÃ¤ÃŸen\n\nâ€¢ Verhalten unter BerÃ¼cksichtigung der Ã¶rtlichen Besonderheiten unterwiesen sein. Als\n\nâ€¢bahntechnisch unterwiesene Person dÃ¼rfen sie den geringeren Schutzabstand (z.B. von\n\nâ€¢ 1,5 m bei 15 kV oder bei 25 kV) anwenden. Personen, die nicht bahntechnisch unterwie-\n\nâ€¢ sene Person sind, mÃ¼ssen als â€želektrotechnischer Laieâ€œ einen grÃ¶ÃŸeren Schutzabstand\n\nâ€¢ (z.B. 3,0 m statt 1,5 m bei 15 kV oder bei 25 kV) zu unter Spannung stehenden Teilen der\n\nâ€¢ Oberleitung einhalten.\n\nâ€¢\n\nDer EBL des EIU gibt bekannt\n\nâ€¢ - den Mitarbeitern des EIU: Die fÃ¼r die operative BetriebsfÃ¼hrung der Fahrleitungs-\n\nâ€¢ anlage und der mit der EntstÃ¶rung und Instandhaltung zustÃ¤ndigen Stellen oder\n\nâ€¢ Mitarbeiter,\n\nâ€¢ - dem EVU / den Mitarbeitern des EVU: Die Unfallmeldestelle.\n\nâ€¢",240,"{\"canonical_url\":\"https://www.dbinfrago.com/resource/blob/13174622/b60c3e17d5793a2e92c45c5499bc5362/Ril-438-INB-2026-data.pdf\",\"normalized_sha256\":\"896af7cb568779272b6567f3e92facbd6eb0db60f9e6d474fac6b4b555777da5\",\"page\":118,\"source_id\":\"src_756ac05064c14207f798\",\"source_sha256\":\"f01276e5713c693152de0735b74de84079760d1b3cbcf4727396e73538ad50e0\",\"source_version_id\":\"sv_4f517b21bbdd70a0c6fcfe5c\"}","76d5720d30de56c52811ad2bd965f8fa625d4e1ec85a4037db7a4fe87b8cd9cf"],["chunk_330f3c7a4188f0cb7bd53105","wiki/sources/ril-438-inb-2026-data.md",193,"Seite 118","Werden Arbeiten von Auftragnehmern ausgefÃ¼hrt, mÃ¼ssen die ausfÃ¼hrenden Mitarbeiter\n\nâ€¢ ebenfalls bahntechnisch unterwiesen sein und die Ã¶rtlichen Besonderheiten in den Ar-\n\nâ€¢ beitsbereichen kennen.\n\nâ€¢\n\n(2) Es muss stets angenommen werden, dass alle Teile der Fahrleitung und Bahnener-\n\nâ€¢ gieleitung unter Hochspannung stehen, solange nicht einwandfrei festgestellt ist, dass sie\n\nâ€¢ ausgeschaltet und sichtbar bahngeerdet sind. Nicht nur die unmittelbare BerÃ¼hrung unter\n\nâ€¢ Spannung stehender Teile sondern auch die mittelbare Ã¼ber GegenstÃ¤nde (z. B. Stangen,\n\nâ€¢ Wasserstrahl) oder aber die AnnÃ¤herung kann tÃ¶dlich wirken. Das gilt insbesondere auch\n\nâ€¢ fÃ¼r Fahrleitungsanlagen in WerkstÃ¤tten, an Ladegleisen und Anschlussgleisen.\n\nâ€¢\n\nBeispiele fÃ¼r GefÃ¤hrdungen aus der Fahrleitungsanlage und der RÃ¼ckstromfÃ¼hrung:\n\nâ€¢ - GefÃ¤hrdung durch direktes BerÃ¼hren bzw. gefÃ¤hrliches AnnÃ¤hern an stromfÃ¼hren-\n\nâ€¢ de Teile direkt mit dem KÃ¶rper oder mit leitfÃ¤higen GegenstÃ¤nden\n\nâ€¢ - G efÃ¤hrdung bei Bau- und/oder Erdarbeiten in der NÃ¤he von Fahrleitungsanlagen\n\nâ€¢ - GefÃ¤hrdung aufgrund einer herabhÃ¤ngenden bzw. abgerissenen Oberleitung (Span-\n\nâ€¢ nungstrichter-Problematik)\n\n(B 22) â€“ 94 â€“",159,"{\"canonical_url\":\"https://www.dbinfrago.com/resource/blob/13174622/b60c3e17d5793a2e92c45c5499bc5362/Ril-438-INB-2026-data.pdf\",\"normalized_sha256\":\"896af7cb568779272b6567f3e92facbd6eb0db60f9e6d474fac6b4b555777da5\",\"page\":118,\"source_id\":\"src_756ac05064c14207f798\",\"source_sha256\":\"f01276e5713c693152de0735b74de84079760d1b3cbcf4727396e73538ad50e0\",\"source_version_id\":\"sv_4f517b21bbdd70a0c6fcfe5c\"}","6b97d9383b260792df639ec5ca43ede86876aae384bf43afa2ad1fb6a7306406"],["chunk_32245360376375f41cea4e49","wiki/sources/ril-438-inb-2026-data.md",194,"Seite 119","noch Anlage 1\n\n- GefÃ¤hrdung aufgrund von defekten oder fehlenden RÃ¼ckstromfÃ¼hrungen und Bah- â€¢\n\nnerdungen (z.B. RÃ¼ckleiterseile (an Trennstellen der Schienen)), Masterden (zwi- â€¢\n\nschen Oberleitungsmast und Schiene), Betriebserden (z.B. zwischen Weichenhei- â€¢\n\nzungsanlagen und Schiene) â€¢\n\n- GefÃ¤hrdung aufgrund von FremdkÃ¶rpern, die sich in der Fahrleitungsanlage befinden, â€¢\n\n- G efÃ¤hrdung aufgrund parallel fÃ¼hrender Oberleitungen (Induktions-Problematik) â€¢\n\n(3) Jeder Mitarbeiter im Eisenbahnbetrieb hat auf den ordnungsgemÃ¤ÃŸen Zustand der â€¢\n\nAnlagen fÃ¼r den elektrischen Bahnbetrieb, insbesondere der Fahrleitung zu achten. â€¢\n\nErkennbare SchÃ¤den und UnregelmÃ¤ÃŸigkeiten wie z. B: â€¢\n\nâ€¢ A uftreten von Rauch und Feuer â€¢\n\nâ€¢ herabhÃ¤ngende Leitungen â€¢\n\nâ€¢ g ebrochene Isolatoren â€¢\n\nâ€¢ b eschÃ¤digte oder fehlende RÃ¼ckleiter, â€¢\n\nâ€¢ beschÃ¤digte oder fehlende Verbinder der Bahnenergieleitungen â€¢\n\nâ€¢ a uÃŸergewÃ¶hnliche Bewegungen des Kettenwerks und der Stromabnehmer â€¢\n\nsind zu melden. â€¢\n\nDer EBL des EIU gibt bekannt, welche Stellen auf welchem Meldeweg Ã¼ber SchÃ¤den und â€¢\n\nUnregelmÃ¤ÃŸigkeiten sofort zu verstÃ¤ndigen sind. â€¢\n\n(3a) Elektrische Triebfahrzeuge und Mehrkrafttriebfahrzeuge dÃ¼rfen nur dann mit geho- â€¢\n\nbenem Stromabnehmer in ZÃ¼gen eingesetzt werden, wenn dies im Fahrplan angegeben â€¢\n\nist. Beim Rangieren dÃ¼rfen nur dann elektrische Triebfahrzeuge und Mehrkrafttriebfahr- â€¢\n\nzeuge mit gehobenem Stromabnehmer bewegt werden, wenn die Fahrleitung vorhanden â€¢\n\nund eingeschaltet ist. â€¢\n\n(4) Fahrzeuge mit gehobenem Stromabnehmer dÃ¼rfen grundsÃ¤tzlich nur dann in einen â€¢\n\nGleisabschnitt eingelassen werden, wenn die Fahrleitung eingeschaltet ist (s. aber (6)). â€¢\n\nFÃ¼r den Bereich des Durchrutschweges darf die Fahrleitung jedoch ausgeschaltet sein. â€¢",241,"{\"canonical_url\":\"https://www.dbinfrago.com/resource/blob/13174622/b60c3e17d5793a2e92c45c5499bc5362/Ril-438-INB-2026-data.pdf\",\"normalized_sha256\":\"896af7cb568779272b6567f3e92facbd6eb0db60f9e6d474fac6b4b555777da5\",\"page\":119,\"source_id\":\"src_756ac05064c14207f798\",\"source_sha256\":\"f01276e5713c693152de0735b74de84079760d1b3cbcf4727396e73538ad50e0\",\"source_version_id\":\"sv_4f517b21bbdd70a0c6fcfe5c\"}","f64e2a02dcf38825a091f619417fa6b7707e74738430610ded5894395ebb44ba"],["chunk_c45a3645d488ace9934b8296","wiki/sources/ril-438-inb-2026-data.md",195,"Seite 119","Gleise, deren Fahrleitung abgeschaltet oder â€“ ohne den Regellichtraum einzuschrÃ¤nken\n\nâ€“ gestÃ¶rt ist, sind nicht zu sperren. Es ist das Merkschild â€žGleis fÃ¼r Fahrzeuge mit gehobenem Stromabnehmer nicht befahrbarâ€œ nach Anlage 18 an der Fernmeldeanlage anzubringen. Sollen ZÃ¼ge oder Rangierfahrten in ein solches Gleis eingelassen werden, so hat\n\nsich der die Fahrt zulassende Mitarbeiter im Eisenbahnbetrieb (z. B. Zugleiter, Fahrdienstleiter, Ã¶rtlicher Betriebsbedienster, WeichenwÃ¤rter) vorher zu vergewissern, dass sie nicht\n\nvon Triebfahrzeugen mit angelegten Stromabnehmern befÃ¶rdert werden.\n\n(5) Fahrzeuge mit gehobenem Stromabnehmer dÃ¼rfen in spannungslose Schaltgruppen/ â€¢\n\nSchaltabschnitte oder in Speisebezirke ungleicher Frequenz bzw. Spannung nur einge- â€¢\n\nlassen werden, wenn der TriebfahrzeugfÃ¼hrer darÃ¼ber z. B. durch die SbV, Signale, Be- â€¢\n\ntriebsanweisung oder Befehle unterrichtet ist und angewiesen wurde, den Stromabnehmer â€¢\n\nzu senken. Der TriebfahrzeugfÃ¼hrer darf in einen solchen Abschnitt nur einfahren, wenn er â€¢\n\n- diesen mit Schwung durchfahren kann, â€¢\n\n- diesen mit einer anderen Traktionsart befahren kann oder â€¢\n\n- an der vorgesehenen Stelle anhalten kann. â€¢\n\n(B 22) â€“ 95 â€“",166,"{\"canonical_url\":\"https://www.dbinfrago.com/resource/blob/13174622/b60c3e17d5793a2e92c45c5499bc5362/Ril-438-INB-2026-data.pdf\",\"normalized_sha256\":\"896af7cb568779272b6567f3e92facbd6eb0db60f9e6d474fac6b4b555777da5\",\"page\":119,\"source_id\":\"src_756ac05064c14207f798\",\"source_sha256\":\"f01276e5713c693152de0735b74de84079760d1b3cbcf4727396e73538ad50e0\",\"source_version_id\":\"sv_4f517b21bbdd70a0c6fcfe5c\"}","814495d4eddd070c58873fc77c802cb9871cb32a30783c5b424b22fd4920afe3"],["chunk_247bb138df5bf9d6d62a0c17","wiki/sources/ril-438-inb-2026-data.md",196,"Seite 120","noch Anlage 1\n\nâ€¢ (6) FÃ¼r das Einfahren mit angelegtem Stromabnehmer in spannungslose Schaltgruppen/\n\nâ€¢ Schaltabschnitte/ Schutzstrecken oder in Speisebezirke ungleicher Frequenz bzw. Span-\n\nâ€¢ nung werden vom EBL des EIU besondere Anweisungen gegeben.\n\nâ€¢ (6a) FÃ¼r Mehrkrafttriebfahrzeuge wird im Fahrplan oder in der SbV der Ort des Traktions-\n\nâ€¢ artwechsels angegeben.\n\nâ€¢ (6b) Der EBL des EIU gibt in der SbV bekannt:\n\nâ€¢ - betriebliche Regelungen in Zusammenhang mit der verwendeten Fahrleitungsbau-\n\nâ€¢ art (z. B. kein Anheben des Stromabnemers unter Kunstbauten);\n\nâ€¢ - Regelungen bei Raureif oder Eisregen sowie\n\nâ€¢ - Regelungen beim Fehlen von Fahrdrahtspannung.\n\nâ€¢ (6c) Der EBL des EIU gibt in der SbV bekannt, auf welchen Abschnitten eine Oberstrom-\n\nâ€¢ begrenzung fÃ¼r Fahrzeuge in Bewegung besteht und die dazu zu beachtenden betriebli-\n\nâ€¢ chen Regelungen.\n\nâ€¢ (6d) Der EBL des EIU gibt in der SbV bekannt, welche Oberstrombegrenzung fÃ¼r Fahr-\n\nâ€¢ zeuge im Stillstand (z.B. beim Laden von Traktionsakkumulatoren) besteht und die dazu\n\nâ€¢ zu beachtenden betrieblichen Regelungen.\n\nâ€¢ (6e) Der EBL des EIU gibt bekannt:\n\nâ€¢ - Lage und LÃ¤nge von Fahrleitungsschutzstrecken\n\nâ€¢ II. Arbeiten an oder in der NÃ¤he der Fahrleitungsanlagen und elektrischen Fahrzeugen\n\nâ€¢ (7) (bleibt frei)\n\nâ€¢ (8) FÃ¼r Arbeiten an oder in der NÃ¤he von Fahrleitungsanlagen sind die vorgegebenen\n\nâ€¢ SicherheitsmaÃŸnahmen anzuwenden. Personen, die auf elektrisch betriebenen Strecken\n\nâ€¢ tÃ¤tig sind, mÃ¼ssen bahntechnisch unterwiesen sein und die Ã¶rtlichen Besonderheiten\n\nâ€¢ kennen. Zudem mÃ¼ssen sie die fÃ¼r ihre TÃ¤tigkeit geforderte Qualifikation besitzen. Die\n\nâ€¢ DurchfÃ¼hrung der Unterweisungen, die erforderlichen Qualifikationen und das Erlangen\n\nâ€¢ dieser Qualifikationen regelt das EIU bzw. EVU im Benehmen mit dem EBL.",265,"{\"canonical_url\":\"https://www.dbinfrago.com/resource/blob/13174622/b60c3e17d5793a2e92c45c5499bc5362/Ril-438-INB-2026-data.pdf\",\"normalized_sha256\":\"896af7cb568779272b6567f3e92facbd6eb0db60f9e6d474fac6b4b555777da5\",\"page\":120,\"source_id\":\"src_756ac05064c14207f798\",\"source_sha256\":\"f01276e5713c693152de0735b74de84079760d1b3cbcf4727396e73538ad50e0\",\"source_version_id\":\"sv_4f517b21bbdd70a0c6fcfe5c\"}","32e85e9e541620b5d4dfa21e593150d2b593d2ec66f609b77ef5136b999f4829"],["chunk_a5609fdf430eff6d6e2cbfc8","wiki/sources/ril-438-inb-2