INSERT INTO wiki_chunks (id,page_path,ordinal,heading_path,text,token_count,source_refs_json,content_sha) SELECT json_extract(value,'$[0]'),json_extract(value,'$[1]'),json_extract(value,'$[2]'),json_extract(value,'$[3]'),json_extract(value,'$[4]'),json_extract(value,'$[5]'),json_extract(value,'$[6]'),json_extract(value,'$[7]') FROM json_each('[["chunk_80f77c5b1cd3e305149ace80","wiki/sources/ril-465-0001-inb-2026-data.md",8,"Seite 5","Betrieb auf Steilstrecken; 465.0001\n\nBesondere Vorschriften Ã¼ber das Bremsen Seite 5\n\nDie TriebfahrzeugfÃ¼hrer, FÃ¼hrer von Nebenfahrzeugen bzw. die\n\nhierfÃ¼r besonders Beauftragten sind fÃ¼r das MitfÃ¼hren der\n\nRadvorleger verantwortlich.\n\n(3) Es mÃ¼ssen mitgefÃ¼hrt werden auf Anzahl\n\n- Lokomotiven 4 Radvorleger\n\n- Triebwagen 2 Radvorleger\n\n- Nebenfahrzeugen\n\nbis 50 t Gesamtgewicht 2 Radvorleger\n\nÃ¼ber 50 t Gesamtgewicht 4 Radvorleger.\n\n7 Bremsen der ZÃ¼ge\n\n(1) ZÃ¼ge mÃ¼ssen mit durchgehender selbsttÃ¤tiger Druckluftbremse Grundsatz\n\ngefahren werden, und alle Fahrzeuge mÃ¼ssen an die\n\nHauptluftleitung angeschlossen sein. Die eingeschalteten\n\nBremsen mÃ¼ssen zu Beginn der Zugfahrt betriebsbereit sein.\n\nFallen Bremsen unterwegs aus, ist nach Abschn. 14 zu\n\nverfahren.\n\n(2) Das erste und letzte Fahrzeug eines Zuges muÃŸ eine selbsttÃ¤tig Erstes und\n\nwirkende Druckluftbremse haben. letztes Fahrzeug\n\n(3) In GÃ¼terzÃ¼ge darf nur ein GÃ¼ter- oder Bahndienstwagen mit GÃ¼terzÃ¼ge\n\neinlÃ¶siger Druckluftbremse, mit schadhafter oder ohne Druckluftbremse eingestellt werden.\n\n(4) Einzeln fahrende Nebenfahrzeuge mit direkter Bremse dÃ¼rfen Nebenfahrzeuge\n\nohne durchgehende selbsttÃ¤tige Druckluftbremse als Zug mit direkter\n\nverkehren (s. aber Abschn. 5 Abs. 7). Bremse\n\n8 Stellung der Triebfahrzeuge im Zug\n\n(1) Bei ZÃ¼gen mit einem Triebfahrzeug muÃŸ dieses - ausgenom- Talfahrt\n\nmen bei Wende- und HilfszÃ¼gen - stets an der Spitze des Zuges\n\nlaufen.\n\nWendezÃ¼ge dÃ¼rfen mit dem Steuerwagen an der Spitze\n\nverkehren, wenn das Triebfahrzeug am ZugschluÃŸ sowohl mit\n\neiner mehrlÃ¶sigen Bremse als auch mit einer dynamischen\n\nBremse ausgerÃ¼stet ist und beide Bremsen vom Steuerwagen\n\naus bedient werden kÃ¶nnen.\n\nBeim Einsatz von zwei Triebfahrzeugen darf das zweite\n\nTriebfahrzeug sowohl an der Spitze (Vorspannlokomotive) als",244,"{\"canonical_url\":\"https://www.dbinfrago.com/resource/blob/13585456/892e2eb6109dd8c867bb021b0a3f34f0/Ril-465-0001-INB-2026-data.pdf\",\"normalized_sha256\":\"bd83ed30fa4558a43fc8fb8e0f2c5223833d4e758b2ae1d83ffbcebda05abab0\",\"page\":5,\"source_id\":\"src_1bc8700e485a94e877dd\",\"source_sha256\":\"3343fdc69309ae8d08edf0347ebca68f95318156ad984c3ea313fbcc2d8ab625\",\"source_version_id\":\"sv_6e450013073701fcec90420a\"}","c55357af6c8561ed8aba500b7513850892a095668a1fd602e5f1ddc16b055825"],["chunk_f1f9539917a35d8604cb1fa6","wiki/sources/ril-465-0001-inb-2026-data.md",9,"Seite 5","auch am SchluÃŸ des Zuges (Schiebelokomotive bzw.\n\nSchluÃŸlokomotive) eingestellt werden. Mehr als zwei\n\nTriebfahrzeuge dÃ¼rfen im Zug nicht eingestellt werden.\n\n(2) Bei ZÃ¼gen mit einem Triebfahrzeug soll dieses in der Regel an Bergfahrt\n\nder Spitze des Zuges eingestellt werden, ausgenommen bei\n\nWendezÃ¼gen.\n\n15.11.1997",43,"{\"canonical_url\":\"https://www.dbinfrago.com/resource/blob/13585456/892e2eb6109dd8c867bb021b0a3f34f0/Ril-465-0001-INB-2026-data.pdf\",\"normalized_sha256\":\"bd83ed30fa4558a43fc8fb8e0f2c5223833d4e758b2ae1d83ffbcebda05abab0\",\"page\":5,\"source_id\":\"src_1bc8700e485a94e877dd\",\"source_sha256\":\"3343fdc69309ae8d08edf0347ebca68f95318156ad984c3ea313fbcc2d8ab625\",\"source_version_id\":\"sv_6e450013073701fcec90420a\"}","375735637e580063dcd16772dc1d66c41a0cadab46f4f2099d2fde8a2ac98043"],["chunk_655d4615825572f152fc021c","wiki/sources/ril-465-0001-inb-2026-data.md",10,"Seite 6","465.0001 Betrieb auf Steilstrecken;\n\nSeite 6 Besondere Vorschriften Ã¼ber das Bremsen\n\nBeim Einsatz von zwei Triebfahrzeugen darf das zweite\n\nTriebfahrzeug an der Spitze (Vorspannlokomotive) oder am\n\nSchluÃŸ des Zuges (Schiebelokomotive bzw. SchluÃŸlokomotive)\n\neingestellt werden.\n\nBeim Einsatz von drei Triebfahrzeugen mÃ¼ssen zwei an der\n\nSpitze und das dritte Triebfahrzeug am SchluÃŸ des Zuges\n\neingestellt werden.\n\nLokomotivzÃ¼ge (3) LokomotivzÃ¼ge dÃ¼rfen nur aus zwei Triebfahrzeugen bestehen.\n\n9 Bremsstellung, Bremsgewicht,\n\nBremsberechnung\n\nTriebfahrzeuge (1) Bei Triebfahrzeugen sind entsprechend der eingestellten\n\nBremsstellung\n\n- bei mehrlÃ¶siger Bremse das Bremsgewicht der Bremsstellung P oder G und\n\n- bei einlÃ¶siger Bremse 80 % des Bremsgewichtes der\n\nBremsstellung P oder G\n\nanzurechnen.\n\nIst an Triebfahrzeugen fÃ¼r Steilstrecken ein besonderes\n\nBremsgewicht angeschrieben, so ist dieses anzurechnen.\n\nBei Triebfahrzeugen in der Bremsstellung R oder P2 dÃ¼rfen nur\n\ndie Bremsgewichte der Bremsstellung P angerechnet werden.\n\nDas Bremsgewicht der dynamischen Bremse darf nicht\n\nangerechnet werden.\n\nReisezug- (2) Bei Reisezugwagen ist stets die wirksamste Bremsstellung\n\nwagen einzustellen. Die Bremsstellung R+Mg darf jedoch nur dann\n\neingestellt werden, wenn der Zug vor oder nach Befahren der\n\nSteilstrecke auch andere Strecken befÃ¤hrt, auf denen diese\n\nBremsstellung erforderlich ist.\n\nBei Wagen in der Bremsstellung R oder R+Mg dÃ¼rfen nur die\n\nBremsgewichte der Bremsstellung P angerechnet werden. Ist\n\nkein Bremsgewicht fÃ¼r die Bremsstellung P angeschrieben oder\n\nist das Eigengewicht kleiner als das Bremsgewicht der\n\nBremsstellung P, ist das Eigengewicht als Bremsgewicht\n\nanzurechnen.\n\nGÃ¼terwagen (3) Das Bremsgewicht eines GÃ¼terwagens mit einlÃ¶siger Bremse",231,"{\"canonical_url\":\"https://www.dbinfrago.com/resource/blob/13585456/892e2eb6109dd8c867bb021b0a3f34f0/Ril-465-0001-INB-2026-data.pdf\",\"normalized_sha256\":\"bd83ed30fa4558a43fc8fb8e0f2c5223833d4e758b2ae1d83ffbcebda05abab0\",\"page\":6,\"source_id\":\"src_1bc8700e485a94e877dd\",\"source_sha256\":\"3343fdc69309ae8d08edf0347ebca68f95318156ad984c3ea313fbcc2d8ab625\",\"source_version_id\":\"sv_6e450013073701fcec90420a\"}","b5a7e5279ae9d943ce44fd68b3fa3a2e49fa356c2ee328b1861452025cf49221"],["chunk_f92fd102c0dc08ef1bf96e1d","wiki/sources/ril-465-0001-inb-2026-data.md",11,"Seite 6","darf nicht angerechnet werden.\n\nScheibenbrem- (4) Wagen mit Scheibenbremse bzw. Kunststoff-Bremsklotzsohlen\n\nsen, Kunststoff- dÃ¼rfen nur auf Steilstrecken mit einer maÃŸgebenden Neigung\n\nBremsklotz- von kleiner als 60 Â‰ eingesetzt werden, wenn im Zug\n\nsohlen mindestens 71 Bremshundertstel vorhanden sind.\n\nBei einer maÃŸgebenden Neigung von gleich/grÃ¶ÃŸer 60 Â‰ dÃ¼rfen\n\ndiese Wagen ausnahmsweise eingesetzt werden, wenn im Zug\n\nzwei Drittel der Wagen mit wirkender Druckluftbremse und\n\nGrauguÃŸbremsklÃ¶tzen ausgerÃ¼stet sind. In diesen FÃ¤llen dÃ¼rfen\n\n15.11.1997",71,"{\"canonical_url\":\"https://www.dbinfrago.com/resource/blob/13585456/892e2eb6109dd8c867bb021b0a3f34f0/Ril-465-0001-INB-2026-data.pdf\",\"normalized_sha256\":\"bd83ed30fa4558a43fc8fb8e0f2c5223833d4e758b2ae1d83ffbcebda05abab0\",\"page\":6,\"source_id\":\"src_1bc8700e485a94e877dd\",\"source_sha256\":\"3343fdc69309ae8d08edf0347ebca68f95318156ad984c3ea313fbcc2d8ab625\",\"source_version_id\":\"sv_6e450013073701fcec90420a\"}","685e33887f41ac056c581312adf2a045877f7aece35f6794c0fc6e2d7a3ac51c"],["chunk_25dd5322e2ab116004ac240b","wiki/sources/ril-465-0001-inb-2026-data.md",12,"Seite 7","Betrieb auf Steilstrecken; 465.0001\n\nBesondere Vorschriften Ã¼ber das Bremsen Seite 7\n\nnur 70 % des Bremsgewichtes des Zuges der Bremsstellung P\n\nangerechnet werden.\n\n(5) FÃ¼r das Erstellen der Streckenbremstafeln sind Bremstafeln\n\n- fÃ¼r Steilstreckenabschnitte mit einem Bremsweg von 400 m\n\ndie Bremstafel fÃ¼r 400 m Bremsweg (Anhang 9) und\n\n- fÃ¼r Steilstreckenabschnitte mit einem Bremsweg von 700 m\n\ndie in den AnhÃ¤ngen 3 und 4 vorgeschriebenen\n\nMindestbremshundertstel\n\nzugrunde zu legen.\n\n(6) Wenn bei Nebenfahrzeugen ein besonderes Bremsgewicht fÃ¼r Bremsgewicht\n\ndie Steilstrecke anzurechnen ist, so ist dies aus der Anschrift an Neben-\n\n(Anschriftentafel) ersichtlich. fahrzeugen\n\n(7) Bei Fahrzeugen, die von einem Nebenfahrzeug mitgefÃ¼hrt Nebenfahrzeug\n\nwerden, sind 80 % des Bremsgewichtes der Bremsstellung P mit AnhÃ¤ngelast\n\nanzurechnen; haben diese Fahrzeuge nur die Bremsstellung G,\n\nsind nur 40 % des Bremsgewichtes der Bremsstellung G\n\nanzurechnen.\n\n(8) FÃ¼r die Steilstreckenabschnitte ist ein gesonderter Bremszettel Bremszettel\n\nauszufertigen, wenn es in den regionalen ZusÃ¤tzen (s. Abschn. 1\n\nAbs. 3) festgelegt ist.\n\n10 Besetzen der Triebfahrzeuge, Steuerwagen,\n\nZÃ¼ge und Nebenfahrzeuge\n\n(1) FÃ¼hrende Triebfahrzeuge und Steuerwagen an der Spitze des Triebfahrzeuge,\n\nZuges sind zusÃ¤tzlich mit einem Triebfahrzeugbegleiter und Steuerwagen,\n\nNebenfahrzeuge mit eigenem Kraftantrieb zusÃ¤tzlich mit einem ZÃ¼ge u. Neben-\n\nBegleiter zu besetzen. fahrzeuge\n\nSie mÃ¼ssen in der Lage sein, den Zug bzw. das Nebenfahrzeug\n\nzum Halten zu bringen und zu sichern.\n\n(2) Am SchluÃŸ des Zuges laufende Triebfahrzeuge (ausgenommen Triebfahrzeuge\n\nbei WendezÃ¼gen) am SchluÃŸ\n\n- sind mit dem TriebfahrzeugfÃ¼hrer allein zu besetzen und\n\n- dÃ¼rfen bei EndfÃ¼hrerstÃ¤nden vom hinteren FÃ¼hrraum aus",243,"{\"canonical_url\":\"https://www.dbinfrago.com/resource/blob/13585456/892e2eb6109dd8c867bb021b0a3f34f0/Ril-465-0001-INB-2026-data.pdf\",\"normalized_sha256\":\"bd83ed30fa4558a43fc8fb8e0f2c5223833d4e758b2ae1d83ffbcebda05abab0\",\"page\":7,\"source_id\":\"src_1bc8700e485a94e877dd\",\"source_sha256\":\"3343fdc69309ae8d08edf0347ebca68f95318156ad984c3ea313fbcc2d8ab625\",\"source_version_id\":\"sv_6e450013073701fcec90420a\"}","12bb68cd3345be185cd6e9d366e8fb049f2021a3f2eb75ff85cd06cb48c0218f"],["chunk_6b1ef103ba6a84484f04933e","wiki/sources/ril-465-0001-inb-2026-data.md",13,"Seite 7","bedient werden.\n\n(3) Bei LokomotivzÃ¼gen mÃ¼ssen beide Triebfahrzeuge besetzt sein. LokomotivzÃ¼ge\n\n11 Besondere MaÃŸnahmen vor dem Befahren der\n\nSteilstrecke\n\n(1) ZusÃ¤tzlich zu den bereits durchgefÃ¼hrten Bremsproben gemÃ¤ÃŸ Bremsprobe an\n\nDS 915 01 - Bremsen im Betrieb bedienen, prÃ¼fen und warten - ZÃ¼gen\n\nmÃ¼ssen bei den von anderen Strecken auf die Steilstrecke\n\nÃ¼bergehenden ZÃ¼gen auf den in den AnhÃ¤ngen 1 bis 8\n\n15.11.1997",62,"{\"canonical_url\":\"https://www.dbinfrago.com/resource/blob/13585456/892e2eb6109dd8c867bb021b0a3f34f0/Ril-465-0001-INB-2026-data.pdf\",\"normalized_sha256\":\"bd83ed30fa4558a43fc8fb8e0f2c5223833d4e758b2ae1d83ffbcebda05abab0\",\"page\":7,\"source_id\":\"src_1bc8700e485a94e877dd\",\"source_sha256\":\"3343fdc69309ae8d08edf0347ebca68f95318156ad984c3ea313fbcc2d8ab625\",\"source_version_id\":\"sv_6e450013073701fcec90420a\"}","7b33c6a0ddbfb75f3ee43f124d5279eb4cc63b70751feccc2a8442080940f1bb"],["chunk_91d06c0450f59a4fe6576a65","wiki/sources/ril-465-0001-inb-2026-data.md",14,"Seite 8","465.0001 Betrieb auf Steilstrecken;\n\nSeite 8 Besondere Vorschriften Ã¼ber das Bremsen\n\ngenannten BahnhÃ¶fen die Bremsen\n\n- der GÃ¼terzÃ¼ge durch eine volle Bremsprobe und\n\n- der ReisezÃ¼ge durch eine vereinfachte Bremsprobe\n\n(PrÃ¼fung am letzten Wagen)\n\ngeprÃ¼ft werden.\n\nBremsprobe an (2) Die Bremsen der Nebenfahrzeuge mÃ¼ssen vor jedem Befahren\n\nNeben- der Steilstrecke vom FÃ¼hrer des Nebenfahrzeuges durch eine\n\nfahrzeugen Bremsprobe nach Anhang VI der DS 915 01 auf Wirksamkeit\n\ngeprÃ¼ft werden.\n\nPrÃ¼fen der (3) Bei GÃ¼terzÃ¼gen sind vor dem Befahren der Steilstrecke die\n\nHandbremsen Wagenhandbremsen auf Wirksamkeit zu prÃ¼fen. FÃ¼r ReisezÃ¼ge\n\nist sicherzustellen, daÃŸ die Handbremsen der Wagen einmal\n\ntÃ¤glich, im Regelfall vor der ersten Zugfahrt, auf Wirksamkeit\n\ngeprÃ¼ft werden. Bei dieser PrÃ¼fung ist bei klotzgebremsten\n\nWagen das feste Anliegen der BremsklÃ¶tze bei gelÃ¶ster\n\nDruckluftbremse zu kontrollieren; bei Scheibenbremsen die\n\nhierfÃ¼r vorhandene Anzeige.\n\nWo das PrÃ¼fen der Handbremse zu erfolgen hat, ist Ã¶rtlich\n\nfestzulegen (s. Abschn. 1 Abs. 3). Werden unterwegs auf der\n\nSteilstrecke Wagen beigestellt, so hat die PrÃ¼fung der\n\nHandbremsen unmittelbar zu erfolgen.\n\nBetriebs- (4) Die TriebfahrzeugfÃ¼hrer und FÃ¼hrer von Nebenfahrzeugen\n\nbremsung haben sich auÃŸerdem durch eine Betriebsbremsung vor der Talfahrt von der ausreichenden Bremswirkung der Druckluftbremse\n\nzu Ã¼berzeugen.\n\nAn ZÃ¼gen, die direkt vor dem GefÃ¤lle beginnen und deren\n\nBremsen nicht mit einer Betriebsbremsung wÃ¤hrend der Fahrt\n\ngeprÃ¼ft werden kÃ¶nnen, ist unmittelbar vor Beginn der Fahrt eine\n\nvolle Bremsprobe auszufÃ¼hren. Die AnwendungsfÃ¤lle sind\n\nfestzulegen (s. Abschn. 1 Abs. 3).\n\nLangsamgang (5) Wenn bei Diesellokomotiven mit Stufengetriebe vor der Talfahrt",239,"{\"canonical_url\":\"https://www.dbinfrago.com/resource/blob/13585456/892e2eb6109dd8c867bb021b0a3f34f0/Ril-465-0001-INB-2026-data.pdf\",\"normalized_sha256\":\"bd83ed30fa4558a43fc8fb8e0f2c5223833d4e758b2ae1d83ffbcebda05abab0\",\"page\":8,\"source_id\":\"src_1bc8700e485a94e877dd\",\"source_sha256\":\"3343fdc69309ae8d08edf0347ebca68f95318156ad984c3ea313fbcc2d8ab625\",\"source_version_id\":\"sv_6e450013073701fcec90420a\"}","334a001f83501bb8d58637f61f9ff9a3227dc7f2ee8663267b98e58681e82b49"],["chunk_cb6f0925592f5c3182917e51","wiki/sources/ril-465-0001-inb-2026-data.md",15,"Seite 8","zur ErhÃ¶hung der Bremskraft der dynamischen Bremse der\n\nLangsamgang eingeschaltet werden muÃŸ, so ist dies im\n\nBuchfahrplan vorgeschrieben.\n\nPrÃ¼fen der (6) Vor jeder Talfahrt ist die Wirksamkeit der dynamischen Bremse\n\ndynamischen zu prÃ¼fen.\n\nBremse\n\nSandstreu- (7) Vor dem Befahren der Steilstrecke haben sich die\n\neinrichtung TriebfahrzeugfÃ¼hrer und FÃ¼hrer von Nebenfahrzeugen zu\n\nÃ¼berzeugen, daÃŸ die Sandstreueinrichtung einwandfrei arbeitet\n\nund ausreichend Sandvorrat vorhanden ist. Bei Fahrzeugen mit\n\neiner Einrichtung Â„Autom